style:
.pilot-command-hero {
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  padding: 32px 36px;
  color: #fff;
  background: linear-gradient(135deg, #002e19 0%, #003d21 45%, #005931 100%);
  box-shadow: 0 12px 40px rgba(0, 89, 49, 0.35);
}
.pilot-command-hero__glow {
  position: absolute;
  right: -40px;
  top: -40px;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: rgba(200, 230, 212, 0.14);
  pointer-events: none;
  animation: pilot-hero-glow 6s ease-in-out infinite;
}
@keyframes pilot-hero-glow {
  0%, 100% { opacity: 0.7; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.06); }
}
@media (prefers-reduced-motion: reduce) {
  .pilot-command-hero__glow { animation: none; }
}
.pilot-command-hero__inner {
  position: relative;
  z-index: 1;
}
.pilot-command-hero__brand {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 8px;
}
.pilot-command-hero__logo-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: #fff;
  border: 1px solid rgba(212, 237, 225, 0.6);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
  flex-shrink: 0;
}
.pilot-command-hero__logo-wrap img {
  width: 44px;
  height: 44px;
  object-fit: contain;
  object-position: center;
  display: block;
}
.pilot-command-hero__eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: #c8e6d4;
}
.pilot-command-hero__title {
  margin: 10px 0 0;
  font-size: 30px;
  font-weight: 800;
  line-height: 1.15;
  color: #fff;
  border: 0;
}
.pilot-command-hero__desc {
  margin: 12px 0 0;
  max-width: 680px;
  font-size: 14px;
  line-height: 1.5;
  opacity: 0.94;
  color: #fff;
}
.pilot-command-hero__pills {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 20px;
}
.pilot-command-hero__pill {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  color: #fff;
}
.pilot-command-hero__cta {
  display: inline-block;
  margin-top: 22px;
  padding: 10px 22px;
  border-radius: 8px;
  background: #fff;
  color: #005931;
  font-weight: 700;
  font-size: 14px;
  text-decoration: none;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12);
  transition: transform 0.15s ease, background 0.15s ease;
}
.pilot-command-hero__cta:hover {
  background: #e8f5ef;
  color: #003d21;
  transform: translateY(-1px);
}
